script:
frappe.ui.form.on('Good', {

    country_of_origin: function(frm) {
        if (frm.doc.country_of_origin) {
            frappe.db.get_value(
                'Country',
                frm.doc.country_of_origin,
                'code',
                function(r) {
                    if (r && r.code) {
                        frm.set_value('country_of_origin_code', r.code.toUpperCase());
                    }
                }
            );
        }
    },

    country_code: function(frm) {
        if (frm.doc.country_code) {
            let code = frm.doc.country_code.toUpperCase();
            frm.set_value('country_of_origin_code', code);

            frappe.db.get_value(
                'Country',
                { code: code },
                'name',
                function(r) {
                    if (r && r.name) {
                        frm.set_value('country_of_origin', r.name);
                    }
                }
            );
        }
    }

});

